parameters.text:
=You are the Processing Agent in a news intelligence pipeline. Clean, verify relevance and tag ONE news article. Return ONLY valid JSON. No markdown fences, no commentary.

Domain relevance rules:
- Technology: keep AI, software, internet, telecom, semiconductors, startups and funding, cybersecurity, big-tech business, tech regulation. Drop gadget deals, shopping guides, game/app reviews, lifestyle.
- Finance: keep markets, RBI/SEBI actions, policy rates, inflation, GDP, banking, earnings, IPOs, M&A, commodities, currency, budget and tax policy. Drop personal-finance tips, lifestyle, sponsored content.
- Politics: keep government decisions, legislation, Parliament, elections, court rulings on public policy, diplomacy, defence policy. Drop celebrity, sport, and crime stories with no policy angle.

Article
Assigned category: {{ $json.category }}
Headline: {{ $json.headline }}
Source: {{ $json.source }}
Published: {{ $json.published }}
URL: {{ $json.url }}
Body: {{ String($json.body || '').slice(0, 6000) }}

Return JSON with exactly these keys:
"relevant": true or false,
"category": "Technology" or "Finance" or "Politics" (change it only if the article clearly belongs elsewhere),
"summary": a 2-3 sentence factual summary using only the article text,
"key_facts": array of up to 5 short factual statements (numbers, dates, decisions),
"entities": object with arrays "companies", "people", "organisations", "countries",
"clean_text": the article text with ads, navigation, bylines, 'read more' and subscription prompts removed. Do not add any facts. Max 300 words.
If the body is only a short snippet, clean_text may simply repeat the snippet.

parameters.jsCode:
// Turn the Processing Agent's JSON into a tagged article. Irrelevant articles are dropped here.
const out = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  const src = $('Skip Already-Stored Articles').itemMatching(i).json;
  const raw = String(inputs[i].json.text || '');
  let p = null;
  try { p = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim()); }
  catch (e) { const m = raw.match(/\{[\s\S]*\}/); try { p = m ? JSON.parse(m[0]) : null; } catch (e2) { p = null; } }
  if (!p) p = { relevant: true, category: src.category, summary: String(src.body || '').slice(0, 400), key_facts: [], entities: {}, clean_text: src.body, parse_failed: true };
  if (p.relevant === false) continue;

  const cats = ['Technology', 'Finance', 'Politics'];
  const category = cats.includes(p.category) ? p.category : src.category;
  const e = p.entities || {};
  const entities = [...(e.companies || []), ...(e.organisations || []), ...(e.people || []), ...(e.countries || [])];
  const d = new Date(src.published);
  const istDate = new Date(d.getTime() + 5.5 * 3600 * 1000).toISOString().slice(0, 10);

  out.push({ json: {
    headline: src.headline, url: src.url, source: src.source,
    also_reported_by: (src.also_reported_by || []).join(', '),
    published: src.published, published_date: istDate, published_ts: Math.floor(d.getTime() / 1000),
    category, summary: p.summary || '', key_facts: Array.isArray(p.key_facts) ? p.key_facts : [],
    entities: [...new Set(entities)].join(', '),
    clean_text: p.clean_text || src.body || '', parse_failed: !!p.parse_failed
  }});
}
return out;

// ~1600 characters ≈ 400 tokens. Every chunk carries its own header so citations and dates survive retrieval.
const TARGET = 1600, OVERLAP = 200;
const out = [];
for (const { json: a } of $input.all()) {
  const header = `Headline: ${a.headline}\nCategory: ${a.category} | Source: ${a.source} | Published: ${a.published_date} | URL: ${a.url}`
               + (a.also_reported_by ? `\nAlso reported by: ${a.also_reported_by}` : '')
               + (a.entities ? `\nEntities: ${a.entities}` : '');
  const body = `Summary: ${a.summary}\n` + (a.key_facts.length ? `Key facts: ${a.key_facts.join('; ')}\n` : '') + a.clean_text;
  const parts = body.match(/[^.!?\n]+[.!?]*\s*|\n/g) || [body];
  const chunks = []; let cur = '';
  for (const s of parts) {
    if ((cur + s).length > TARGET && cur.trim().length) {
      chunks.push(cur.trim());
      const tail = cur.slice(-OVERLAP); cur = tail.slice(tail.indexOf(' ') + 1) + s;
    } else cur += s;
  }
  if (cur.trim()) chunks.push(cur.trim());
  chunks.forEach((c, idx) => out.push({ json: {
    content: `${header}\n[Part ${idx + 1} of ${chunks.length}]\n${c}`,
    headline: a.headline, url: a.url, source: a.source, category: a.category,
    published_date: a.published_date, published_ts: a.published_ts, entities: a.entities,
    also_reported_by: a.also_reported_by, chunk_index: idx
  }}));
}
return out;

// One summary row per run for the Google Sheet "RunLog"
const safe = (n, f) => { try { return f($(n).all()); } catch (e) { return f([]); } };
const count = n => safe(n, a => a.filter(i => i.json && i.json.headline).length);
const parsed = safe('Parse & Tag Articles', a => a.map(i => i.json));
const byCat = c => parsed.filter(p => p.category === c).length;
const errors = [];
for (const k of ['Tech', 'Finance', 'Politics'])
  for (const n of [`${k} Agent - Read RSS`, `${k} Agent - NewsAPI`])
    safe(n, a => a.forEach(i => { if (i.json && i.json.error) errors.push(`${n}: ${i.json.error.message || i.json.error}`); }));
safe('Processing Agent (Claude)', a => a.forEach(i => { if (i.json && i.json.error) errors.push('Processing: ' + (i.json.error.message || i.json.error)); }));

return [{ json: {
  run_at: $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd HH:mm'),
  tech_fetched: count('Tech Agent - Normalise & Filter'),
  finance_fetched: count('Finance Agent - Normalise & Filter'),
  politics_fetched: count('Politics Agent - Normalise & Filter'),
  unique_after_dedupe: count('Dedupe & Rank'),
  new_articles: count('Skip Already-Stored Articles'),
  relevant_stored: parsed.length,
  tech_stored: byCat('Technology'), finance_stored: byCat('Finance'), politics_stored: byCat('Politics'),
  chunks_stored: safe('Chunk Articles (~400 tokens)', a => a.length),
  errors: errors.length ? [...new Set(errors)].join(' | ').slice(0, 1500) : 'none'
}}];

// Runs only after the Qdrant store succeeded. Lists every article processed this run so it is skipped next time.
const storedAt = $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd HH:mm');
const seen = new Set();
const out = [];
for (const i of $('Skip Already-Stored Articles').all()) {
  const url = i.json.url;
  if (!url || seen.has(url)) continue;
  seen.add(url);
  out.push({ json: { url, headline: String(i.json.headline || '').slice(0, 300), category: i.json.category || '', stored_at: storedAt } });
}
return out;

const arts = $input.all().map(i => i.json);
const block = cat => arts.filter(a => a.category === cat)
  .sort((a, b) => (b.also_reported_by ? b.also_reported_by.split(',').length : 0) - (a.also_reported_by ? a.also_reported_by.split(',').length : 0))
  .slice(0, 8)
  .map((a, i) => `${i + 1}. ${a.headline} (${a.source}, ${a.published_date}) ${a.url}\n   ${a.summary}`).join('\n') || 'No new articles today.';
return [{ json: {
  date: $now.setZone('Asia/Kolkata').toFormat('cccc, dd LLLL yyyy'),
  technology: block('Technology'), finance: block('Finance'), politics: block('Politics')
}}];

